var n=`1298-escondidinho`;var t=`world-1298`;var o=`BR`;var a=`south-america`;var s=4;var r=92;var d={en:`Escondidinho`,ua:`Ескондідінью`};var l={en:`Escondidinho is a dish from Brazil featuring cassava root, whole cow milk, ground beef, yellow onion. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Ескондідінью, страва кухні країни Бразилія з такими основними складниками: маніок, цільне коров'яче молоко, яловичий фарш, жовта цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var h=[{en:`Cook the listed ingredients in simmering water for about 27 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 27 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:27,i:[[`cassava-root`,850,`g`],[`water`,1100,`ml`],[`table-salt`,8,`g`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 9 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 9 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:9,i:[[`whole-cow-milk`,200,`ml`],[`unsalted-butter`,55,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 22 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 22 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:22,i:[[`ground-beef`,590,`g`],[`yellow-onion`,160,`g`],[`tomato`,280,`g`],[`garlic`,4,`clove`]]},{en:`Layer the previously prepared components evenly inside a baking dish, serving mold or plate appropriate to the recipe; smooth the surface and avoid mixing the layers.`,ua:`Рівномірно викладіть підготовлені компоненти шарами у формі для запікання, подавання чи на тарілці відповідно до страви; вирівняйте поверхню, не змішуючи шари.`,t:[`layered-assembly`],m:9,i:[[`mozzarella`,200,`g`]]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 25 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 25 хвилин до готовності.`,t:[`baking`],m:25,i:[]}];var m={slug:n,id:t,country:`BR`,region:a,servings:4,minutes:92,title:d,text:l,steps:h};export{o as country,m as default,t as id,r as minutes,a as region,s as servings,n as slug,h as steps,l as text,d as title};